import json

fpath = "/home/ubuntu/.claude-account-4/projects/-home-ubuntu--agent-ml-research-idea-gen-0509-3-projects-solver-trace-ablation/66001352-e738-4329-bbd1-9a766f6fb183/tool-results/mcp-agent-ml-research-read_registry-1778860609862.txt"

with open(fpath, 'r') as f:
    raw = f.read()

outer = json.loads(raw)
inner = json.loads(outer['result'])
exps = inner['data']['experiments']

# Filter and extract structured data
rows = []
for eid, e in exps.items():
    conclusion = (e.get('conclusion') or '').lower()
    if conclusion not in ('success', 'negative'):
        continue

    m = e.get('metrics', {}) or {}
    spec = e.get('spec', {}) or {}

    # Normalize metric extraction - handle nested 'eval' dict in some experiments
    eval_nested = m.get('eval', {}) if isinstance(m.get('eval'), dict) else {}
    h7_nested = m.get('h7_classification', {}) if isinstance(m.get('h7_classification'), dict) else {}
    train_nested = m.get('train', {}) if isinstance(m.get('train'), dict) else {}

    def get_metric(*keys, default=None):
        """Try multiple key variants to find a metric"""
        for k in keys:
            # Check in metrics
            if k in m and m[k] is not None:
                return m[k]
            # Check in nested eval
            if k in eval_nested:
                return eval_nested[k]
            # Check in h7_classification  
            if k in h7_nested:
                return h7_nested[k]
            # Check in train nested
            if k in train_nested:
                return train_nested[k]
            # Check top-level experiment
            if k in e and e[k] is not None:
                return e[k]
        return default

    row = {
        'exp_id': eid,
        'conclusion': conclusion,
        'reward_mode': spec.get('reward_mode', ''),
        'beta': spec.get('beta', ''),
        'seed': spec.get('seed', ''),
        'steps': spec.get('num_steps', '') or get_metric('training_steps', 'train_steps', 'final_step', default=''),
        'model': spec.get('model_name', '') or e.get('model', '') or get_metric('model', default=''),
        # Eval metrics
        'PR': get_metric('eval_prove_rate', 'prove_rate', 'pass_rate'),
        'n_proved': get_metric('eval_n_proved', 'n_proved', 'proved_count'),
        'n_problems': get_metric('eval_n_problems', 'n_problems', 'total_samples'),
        'ISR': get_metric('eval_mean_isr', 'mean_isr', 'isr_mean', 'isr'),
        'ISR_std': get_metric('eval_isr_std', 'isr_std'),
        'ISR_median': get_metric('eval_median_isr', 'median_isr'),
        'proved_only_ISR': get_metric('eval_proved_only_isr', 'proved_only_isr', 'eval_proved_only_mean_isr', 'proved_only_mean_isr'),
        # Taxonomy
        'H7%': get_metric('h7_rate', 'eval_h7_strict_rate', 'h7_strict_rate', 'hacking_rate_strict_h7', 'h7_functional_rate'),
        'H7_count': get_metric('h7_count', 'eval_h7_strict_count', 'h7_strict_count', 'eval_h7_count'),
        'H1%': get_metric('h1_rate', 'eval_h1_strict_rate', 'h1_strict_rate', 'eval_h1_rate'),
        'H1_count': get_metric('h1_count', 'eval_h1_strict_count', 'h1_strict_count', 'eval_h1_count'),
        'H8%': get_metric('h8_conjunction_collapse_rate'),
        'H8_count': get_metric('h8_conjunction_collapse_count', 'h8_count'),
        'genuine%': get_metric('genuine_rate', 'eval_genuine_rate'),
        'genuine_count': get_metric('genuine_count', 'eval_genuine_count'),
        'tautological': get_metric('tautological_collapse'),
        # Training metrics
        'train_PR': get_metric('train_final_prove_rate', 'final_prove_rate'),
        'train_ISR': get_metric('train_final_mean_isr', 'final_mean_isr'),
        'train_loss': get_metric('train_loss', 'train_final_loss', 'final_loss'),
        'train_entropy': get_metric('train_final_entropy', 'final_entropy'),
        'train_runtime_s': get_metric('train_runtime_seconds', 'train_runtime_sec', 'train_runtime_s'),
    }
    rows.append(row)

# Sort by exp_id
rows.sort(key=lambda r: r['exp_id'])

# Print comprehensive table
print(f"{'='*140}")
print(f"COMPREHENSIVE EXPERIMENT METRICS TABLE — {len(rows)} experiments (conclusion=success or negative)")
print(f"{'='*140}")
print()

for r in rows:
    print(f"--- {r['exp_id']} [{r['conclusion'].upper()}] ---")
    if r['reward_mode'] or r['beta'] or r['seed'] or r['steps']:
        parts = []
        if r['model']: parts.append(f"model={r['model']}")
        if r['reward_mode']: parts.append(f"reward={r['reward_mode']}")
        if r['beta']: parts.append(f"β={r['beta']}")
        if r['seed']: parts.append(f"seed={r['seed']}")
        if r['steps']: parts.append(f"steps={r['steps']}")
        print(f"  Config: {', '.join(parts)}")

    # Eval
    eval_parts = []
    if r['PR'] is not None: eval_parts.append(f"PR={r['PR']}")
    if r['n_proved'] is not None: eval_parts.append(f"n_proved={r['n_proved']}")
    if r['n_problems'] is not None: eval_parts.append(f"n_problems={r['n_problems']}")
    if r['ISR'] is not None: eval_parts.append(f"ISR={r['ISR']}")
    if r['ISR_std'] is not None: eval_parts.append(f"ISR_std={r['ISR_std']}")
    if r['ISR_median'] is not None: eval_parts.append(f"ISR_med={r['ISR_median']}")
    if r['proved_only_ISR'] is not None: eval_parts.append(f"ISR*={r['proved_only_ISR']}")
    if eval_parts:
        print(f"  Eval: {', '.join(eval_parts)}")

    # Taxonomy
    tax_parts = []
    if r['H7_count'] is not None: tax_parts.append(f"H7={r['H7_count']}({r['H7%']})")
    if r['H1_count'] is not None: tax_parts.append(f"H1={r['H1_count']}({r['H1%']})")
    if r['H8_count'] is not None: tax_parts.append(f"H8={r['H8_count']}({r['H8%']})")
    if r['genuine_count'] is not None: tax_parts.append(f"genuine={r['genuine_count']}({r['genuine%']})")
    if r['tautological'] is not None: tax_parts.append(f"taut_collapse={r['tautological']}")
    if tax_parts:
        print(f"  Taxonomy: {', '.join(tax_parts)}")

    # Training
    train_parts = []
    if r['train_PR'] is not None: train_parts.append(f"train_PR={r['train_PR']}")
    if r['train_ISR'] is not None: train_parts.append(f"train_ISR={r['train_ISR']}")
    if r['train_loss'] is not None: train_parts.append(f"loss={r['train_loss']}")
    if r['train_entropy'] is not None: train_parts.append(f"entropy={r['train_entropy']}")
    if r['train_runtime_s'] is not None: train_parts.append(f"runtime={r['train_runtime_s']}s")
    if train_parts:
        print(f"  Training: {', '.join(train_parts)}")

    print()

